import { useState } from "react";
import { useNavigate } from "react-router-dom";

function Login() {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    email: "",
    password: "",
  });

  const [showPassword, setShowPassword] = useState(false);

  // 🔹 handle input change
  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value,
    });
  };

  // 🔹 login function
  const handleLogin = (e) => {
    e.preventDefault();

    fetch("http://localhost:8080/api/login", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(form),
    })
      .then((res) => res.json())
      .then((data) => {
        localStorage.setItem("user", JSON.stringify(data));
        alert("Login Successful!");
        navigate("/");
      })
      .catch(() => alert("Login Failed"));
  };

  return (
    <div className="min-h-screen flex flex-col justify-center items-center bg-gray-50 px-4">

      {/* HEADER */}
      <div className="mb-12 text-center">
        <h1 className="text-2xl italic tracking-widest">LUXE</h1>
        <p className="text-sm text-gray-500 mt-2">
          The Essence of Slow Living
        </p>
      </div>

      {/* CARD */}
      <div className="w-full max-w-md bg-white p-8 rounded-lg shadow">

        {/* TITLE */}
        <div className="text-center mb-6">
          <h2 className="text-xl font-semibold">Welcome Back</h2>
          <p className="text-sm text-gray-500">
            Please enter your credentials
          </p>
        </div>

        {/* FORM */}
        <form onSubmit={handleLogin} className="space-y-6">

          {/* EMAIL */}
          <div>
            <label className="text-sm">Email</label>
            <input
              type="email"
              name="email"
              placeholder="name@domain.com"
              value={form.email}
              onChange={handleChange}
              className="w-full border-b py-2 outline-none"
              required
            />
          </div>

          {/* PASSWORD */}
          <div>
            <label className="text-sm">Password</label>

            <div className="relative">
              <input
                type={showPassword ? "text" : "password"}
                name="password"
                value={form.password}
                onChange={handleChange}
                placeholder="••••••••"
                className="w-full border-b py-2 outline-none"
                required
              />

              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-0 top-2 text-sm"
              >
                👁
              </button>
            </div>
          </div>

          {/* BUTTON */}
          <button
            type="submit"
            className="w-full bg-black text-white py-3 rounded"
          >
            Login
          </button>
        </form>

        {/* DIVIDER */}
        <div className="flex items-center my-6">
          <div className="flex-grow border-t"></div>
          <span className="mx-2 text-sm text-gray-400">OR</span>
          <div className="flex-grow border-t"></div>
        </div>

        {/* SOCIAL (UI ONLY) */}
        <div className="grid grid-cols-2 gap-3">
          <button className="border py-2 rounded">Google</button>
          <button className="border py-2 rounded">Apple</button>
        </div>

        {/* REGISTER LINK */}
        <p className="text-center text-sm mt-6">
          Don’t have an account?{" "}
          <span
            onClick={() => navigate("/register")}
            className="text-blue-500 cursor-pointer"
          >
            Sign Up
          </span>
        </p>
      </div>
    </div>
  );
}

export default Login;
